SELECT p.category, CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, COUNT(DISTINCT oi.unit_price) AS unique_orders, AVG(oi.unit_price) AS avg_unit_price FROM order_items oi LEFT JOIN products p ON oi.product_id = p.id GROUP BY p.category, CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY unique_orders ASC, category ASC, launch_cohort ASC LIMIT 5;
